def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from alive opponents (immediate reaction only)
    yesterday_bids = []
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate how competitive the field was yesterday
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        second_prev = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev
    else:
        highest_prev = 0.0
        second_prev = 0.0

    # Target bid logic:
    # - If others were extremely aggressive (>= 85% of salary), only overtake if we can afford it.
    # - Otherwise, bid moderately to beat typical bids.
    # - Scale with our urgency (hp and no_water_days).
    urgency = 0.0
    if hp <= 2.0:
        urgency += 1.0
    if no_water_days >= 2:
        urgency += 0.7
    if hp <= 4.0:
        urgency += 0.4

    # Base competitiveness threshold based on supply (tighter supply -> higher chance we must win)
    # supply is between 15 and 25; map to [0,1]
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # When supply is low, we need to be more aggressive.
    aggressiveness = 0.55 + (1.0 - supply_norm) * 0.25 + urgency * 0.25
    if aggressiveness > 0.95:
        aggressiveness = 0.95

    # Determine a candidate bid relative to yesterday's highest/typical
    # Use a small overbid to beat the likely winner without matching the full highest.
    candidate = None
    if highest_prev >= DAILY_SALARY * 0.85:
        # Cindy/David-like behavior: they overbid; avoid matching exactly unless urgent.
        # Bid around 0.65-0.9 of salary depending on urgency.
        candidate = DAILY_SALARY * (0.65 + 0.25 * urgency)
        # Also ensure we can beat the top if we must
        candidate = max(candidate, second_prev + 1.5)
    else:
        # Moderate bids: bid around (0.45-0.8) salary and slightly above second_prev
        candidate = DAILY_SALARY * aggressiveness
        if second_prev > 0.0:
            candidate = max(candidate, second_prev + 1.0)

    # If our HP is very low, push harder; if HP is high, conserve.
    if hp <= 2.0:
        candidate = max(candidate, DAILY_SALARY * 0.9)
    elif hp >= 8.0 and urgency < 0.4:
        candidate = min(candidate, DAILY_SALARY * 0.6)

    # Convert to final bid constrained by budget.
    bid = max(0.0, min(budget, candidate))

    # Safety: if budget is tiny, bid what we can.
    if bid <= 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimally to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Analyze yesterday's bids and identify David
    yesterday_bids = []
    david_alive = False
    david_yesterday_bid = 0

    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])
            if opp_id == "David":
                david_alive = True
                if prev and prev.get('bid') is not None:
                    david_yesterday_bid = prev['bid']

    # --- Bidding Logic ---
    my_current_bid = 0

    # 1. Emergency Bid (Low HP)
    if my_status['hp'] <= 2:
        # Critical HP, bid very high to survive
        my_current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        # Low HP, bid high
        my_current_bid = DAILY_SALARY * 0.8
    else:
        # 2. Normal Play - React to David or highest opponent bid
        base_target_bid = DAILY_SALARY * 0.5 # Default conservative bid

        if david_alive:
            # David is the primary competitor. Try to outbid him.
            if david_yesterday_bid > 0:
                # Try to beat his yesterday's bid by a small margin
                base_target_bid = min(DAILY_SALARY * 0.9, david_yesterday_bid + 5)
            else:
                # If no yesterday bid for David, assume he's strong
                base_target_bid = DAILY_SALARY * 0.85
        elif yesterday_bids:
            # David is not alive, but other opponents are. React to the highest bid.
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid >= DAILY_SALARY * 0.7:
                base_target_bid = min(DAILY_SALARY * 0.8, highest_prev_bid + 2)
            else:
                base_target_bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)

        # 3. Adjust for late game (more aggressive if budget allows)
        days_left = EPISODE_DAYS - day_context['day'] + 1
        if days_left <= 3 and my_status['budget'] > DAILY_SALARY * 2: # If enough budget for a few more days
            base_target_bid = max(base_target_bid, DAILY_SALARY * 0.9)

        my_current_bid = base_target_bid

    # Ensure bid does not exceed current budget
    final_bid = min(my_status['budget'], my_current_bid)

    # Ensure a minimum bid to stay in contention
    min_bid_floor = DAILY_SALARY * 0.1
    return max(min_bid_floor, final_bid)

